import{_ as l,o,c as a,a2 as t}from"./chunks/framework.DpXDHk3d.js";const d=JSON.parse('{"title":"14.5 安全操作与触电急救实操","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-5-an-quan-cao-zuo-yu-chu-dian-ji-jiu-shi-cao.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-5-an-quan-cao-zuo-yu-chu-dian-ji-jiu-shi-cao.md","lastUpdated":1793096070000}'),r={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-5-an-quan-cao-zuo-yu-chu-dian-ji-jiu-shi-cao.md"};function n(s,i,e,u,g,h){return o(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="_14-5-安全操作与触电急救实操" tabindex="-1">14.5 安全操作与触电急救实操 <a class="header-anchor" href="#_14-5-安全操作与触电急救实操" aria-label="Permalink to &quot;14.5 安全操作与触电急救实操&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>安全操作和触电急救是实操考核里&quot;最不能出错&quot;的项目——因为它直接关乎生命。这一节把安全用具使用和心肺复苏的规范动作过一遍。</p><h2 id="一、安全用具使用实操-规范动作" tabindex="-1">一、安全用具使用实操(规范动作) <a class="header-anchor" href="#一、安全用具使用实操-规范动作" aria-label="Permalink to &quot;一、安全用具使用实操(规范动作)&quot;">​</a></h2><p><strong>穿戴检查</strong>:</p><ul><li><strong>绝缘手套</strong>:检查外观无破损,充气/双手对折检查<strong>不漏气</strong>;戴上后<strong>手套口套在衣袖外</strong>;</li><li><strong>绝缘鞋</strong>:干燥、无破损;</li><li><strong>安全帽</strong>:戴正,系好下颌带;</li><li><strong>安全带</strong>:登高作业,系紧,<strong>高挂低用</strong>。</li></ul><p><strong>验电操作</strong>:</p><ul><li>用<strong>试电笔</strong>先在有电设备上验证完好;</li><li>再对检修设备逐相验电;</li><li>高压验电器配合绝缘杆,注意安全距离。</li></ul><blockquote><p>⚠️ 扣分点:不检查手套破损、手套口塞进袖口、验电前不验证验电器——都是不规范动作。</p></blockquote><h2 id="二、低压验电的正确做法-口述-动作" tabindex="-1">二、低压验电的正确做法(口述+动作) <a class="header-anchor" href="#二、低压验电的正确做法-口述-动作" aria-label="Permalink to &quot;二、低压验电的正确做法(口述+动作)&quot;">​</a></h2><ol><li>手接触<strong>笔尾金属体</strong>;</li><li>笔尖接触被测导体;</li><li>氖泡<strong>亮</strong>表示有电,不亮表示无电(也需注意笔本身完好);</li><li>使用前先在<strong>确认有电</strong>的地方验证。</li></ol><h2 id="三、触电急救实操-心肺复苏" tabindex="-1">三、触电急救实操(心肺复苏) <a class="header-anchor" href="#三、触电急救实操-心肺复苏" aria-label="Permalink to &quot;三、触电急救实操(心肺复苏)&quot;">​</a></h2><p>按标准流程做:</p><ol><li><strong>现场安全</strong>:确认环境安全(或先断电、脱离电源);</li><li><strong>判断</strong>:拍肩呼唤、观察胸腹起伏、判断有无心跳呼吸;</li><li><strong>呼救</strong>:喊人帮忙、拨打 120;</li><li><strong>开放气道</strong>:仰头抬颏,清理口腔异物;</li><li><strong>胸外按压</strong>: <ul><li>位置:两乳头连线中点;</li><li>深度:5~6 cm;</li><li>频率:100~120 次/分;</li></ul></li><li><strong>人工呼吸</strong>:捏鼻,口对口吹气 1 秒,见胸廓起伏;</li><li><strong>循环</strong>:按压 30 次 + 吹气 2 次,持续进行。</li></ol><blockquote><p>💡 实操考核常见流程:<strong>&quot;先断电/安全 → 判断 → 呼救 → 按压吹气 30:2 循环&quot;</strong>,每一步都要做出来、说出来。</p></blockquote><h2 id="四、常见被扣分点-务必避免" tabindex="-1">四、常见被扣分点(务必避免) <a class="header-anchor" href="#四、常见被扣分点-务必避免" aria-label="Permalink to &quot;四、常见被扣分点(务必避免)&quot;">​</a></h2><ul><li>抢救前<strong>未判断意识/呼吸</strong>就直接按压;</li><li>按压<strong>位置偏</strong>(过高/过低/偏移);</li><li>按压<strong>深度不足、频率过快过慢</strong>;</li><li>吹气前<strong>未开放气道</strong>(气吹不进去);</li><li><strong>中断按压时间过长</strong>(换人/检查拖太久)。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 手套检查破损、套在衣袖外;安全带高挂低用。</li><li>✅ 试电笔:接触笔尾金属,先验证再验电。</li><li>✅ 心肺复苏:判断→呼救→30:2 循环,位置深度频率要标准。</li><li>⚠️ 易混点:先判断再按压,别跳过&quot;判断&quot;直接按;按压是重点,吹气前必开放气道。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>安全用具:检查→规范穿戴→规范使用。</li><li>验电:验证→逐相→看氖泡。</li><li>急救:断电→判断→呼救→按压吹气 30:2,坚持到底。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)戴绝缘手套前应检查有无破损、漏气。( )</li><li>(判断)心肺复苏前,应先判断触电者有无意识和呼吸。( )</li><li>(单选)胸外按压与人工呼吸的正确比例是()。 A. 15:1　B. 30:2　C. 5:1　D. 2:30</li><li>(判断)人工呼吸前应开放气道(仰头抬颏)。( )</li><li>(判断)急救过程中,胸外按压应尽量减少中断。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。用前必须检查绝缘手套是否完好。</li><li><strong>√</strong>。先判断意识、呼吸、心跳,再决定急救方式。</li><li><strong>B</strong>。30 次按压 : 2 次吹气。</li><li><strong>√</strong>。开放气道才能把气吹进去。</li><li><strong>√</strong>。减少中断,保证按压有效。</li></ol></details>',24)])])}const q=l(r,[["render",n]]);export{d as __pageData,q as default};
